css:
.qb-quote { font-family: 'Courier New', monospace; background: repeating-linear-gradient(#fffdf5, #fffdf5 27px, #d4e8f7 28px); color: #333; padding: 16px 20px 24px 48px; margin: 12px 0; border-radius: 4px; box-shadow: 2px 2px 6px rgba(0,0,0,0.25); position: relative; line-height: 28px; }
.qb-meta { font-size: 0.8em; color: #c0392b; text-transform: uppercase; letter-spacing: 0.08em; }
.qb-divider { border: none; border-top: 1px solid #e8a0a0; margin: 4px 0 8px 0; }
.qb-quote-text { white-space: pre-wrap; }
.qb-author { text-align: right; font-style: italic; margin-top: 8px; }
.qb-site-header { display: flex; justify-content: space-between; font-size: 0.75em; color: #999; margin-top: 12px; }
.qb-rating { margin-top: 8px; color: #b8960c; font-weight: bold; }
.qb-source-url { margin-top: 8px; font-size: 0.8em; }
.qb-source-url a { color: #666; }
.qb-branding { margin-top: 10px; font-size: 0.75em; color: #bbb; text-align: center; }
